    }
    else { 
      set repObj = hddRepResponse.listOfHDDobj.GetAt(1)
      if ( repObj'="") {
	     If repObj.BillingType '=""{
		    set retStr = repObj.BillingType
	        $$$TRACE("Web service returned billing type: "_retStr_" for " _ patientTypeNcid_"|"_svcNcid)
	     }else{
		     If repObj.errText'=""{
		        set status = ..ExceptionHandler(repObj.errText, process)	        				
		    }
		 }
      }
    }

	return status

$$$TRACE("Error Text(In Util): "_errMsg)
